changeSet.sql:
INSERT IGNORE INTO usm_permission_api (api, TYPE, is_whitelisted, DESCRIPTION, permission_id)
             SELECT '/api/aip/skills', 'GET', 0, 'List skills - icip-skill-controller',
             id FROM usm_permissions WHERE module='cip' AND permission='cip-skills-list' LIMIT 1;

INSERT IGNORE INTO usm_permission_api (api, TYPE, is_whitelisted, DESCRIPTION, permission_id)
             SELECT '/api/aip/skills/create', 'POST', 0, 'Create skill - icip-skill-controller',
             id FROM usm_permissions WHERE module='cip' AND permission='cip-skills-create' LIMIT 1;

INSERT IGNORE INTO usm_permission_api (api, TYPE, is_whitelisted, DESCRIPTION, permission_id)
             SELECT '/api/aip/skills/[0-9]*', 'GET', 0, 'Get skill by id - icip-skill-controller',
             id FROM usm_permissions WHERE module='cip' AND permission='cip-skills-getById' LIMIT 1;

INSERT IGNORE INTO usm_permission_api (api, TYPE, is_whitelisted, DESCRIPTION, permission_id)
             SELECT '/api/aip/skills/[0-9]*', 'PUT', 0, 'Update skill - icip-skill-controller',
             id FROM usm_permissions WHERE module='cip' AND permission='cip-skills-update' LIMIT 1;

INSERT IGNORE INTO usm_permission_api (api, TYPE, is_whitelisted, DESCRIPTION, permission_id)
             SELECT '/api/aip/skills/[0-9]*', 'DELETE', 0, 'Delete skill - icip-skill-controller',
             id FROM usm_permissions WHERE module='cip' AND permission='cip-skills-delete' LIMIT 1;
